MAP
    NAME "SS_MAP_CORT_PROSPECTOS_CORTES"
    INCLUDE 'includes/globals.map'
    WEB 
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_prospectos_cortes.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_CORT_PROSPECTOS_CORTES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion_gestion_infra.map'
        DATA "gm_predio from (select vwpc.gm_predio,vwpc.id_predio,mcr.cl_estatus_registro AS cl_estatus_impresion from op.mv_gm_predio_cuenta vwpc join com.mv_limitacion mcr ON mcr.no_cuenta = vwpc.no_cuenta where mcr.cl_trabajo_solicitado = '1') as cr using unique id_predio using srid=32614"
        TYPE polygon
        CLASSITEM "cl_estatus_impresion"
        CLASS
            NAME "prospecto para limitación no impreso"
            EXPRESSION 'C'
            STYLE
                COLOR 255 60 60
            END #STYLE
        END #CLASS
        CLASS
            NAME "prospecto para limitación impreso"
            EXPRESSION 'I'
            STYLE
                COLOR 150 150 255
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP